<script>
const service=document.getElementById('service'),date=document.getElementById('date'),slots=document.getElementById('slots'),time=document.getElementById('time'),btn=document.getElementById('submitBtn'),help=document.getElementById('serviceHelp');
function ready(){btn.disabled=!(service.value&&date.value&&time.value)}
service.addEventListener('change',()=>{const o=service.options[service.selectedIndex];help.textContent=o.dataset.desc||'Select the meeting that best matches what you need.';time.value='';loadSlots()});date.addEventListener('change',()=>{time.value='';loadSlots()});
async function loadSlots(){ready();if(!service.value||!date.value){slots.innerHTML='<div class="empty">Choose a service and date to see available times.</div>';return}slots.innerHTML='<div class="empty">Checking availability…</div>';try{const r=await fetch(`{{ route('booking.slots') }}?service=${encodeURIComponent(service.value)}&date=${encodeURIComponent(date.value)}`);const d=await r.json();if(!d.slots.length){slots.innerHTML='<div class="empty">No times are available on this date. Please choose another day.</div>';return}slots.innerHTML=d.slots.map(s=>`<button type="button" class="slot" data-value="${s.value}">${s.label}</button>`).join('');slots.querySelectorAll('.slot').forEach(el=>el.addEventListener('click',()=>{slots.querySelectorAll('.slot').forEach(x=>x.classList.remove('active'));el.classList.add('active');time.value=el.dataset.value;ready()}))}catch(e){slots.innerHTML='<div class="empty">Availability could not be loaded. Please try again.</div>'}}
if(service.value&&date.value)loadSlots();ready();
</script></body></html>
